  const j = s.id*31.7 + (s.gen = (s.gen||0) + 1)*7.13;
  s.pts = [{ x: (fr(j*1.7)*1.20 - .10)*width, y: height*(1.02 + fr(j*2.9)*.06), f: 1 }];
  s.ang = -Math.PI*.5 + (fr(j*3.3)-.5)*.5;
  s.grip = -1; s.gripAng = 0; s.held = 0; s.nut = fr(j*4.1)*6.28; s.acc = 0;
  s.tend = []; s.leaf = []; s.gap = 0; s.age = 0;
  s.hj = (fr(j*5.5)-.5)*26; s.vig = .7 + fr(j*6.7)*.6;
  s.life = 15 + fr(j*7.9)*8; s.hold = 5 + fr(j*8.3)*6; s.sen = 6 + fr(j*9.1)*5;
  s.ph = fr(j*11.3)*6.28; s.sense = (s.id % 2) ? 1 : -1;
