      const p = s.pts[s.pts.length-1];
      s.nut += .42 + fr(s.id*7.7)*.3;
      let tgt;
      if (s.grip >= 0) { tgt = s.gripAng + Math.sin(s.nut*.5)*.1;
        if (++s.held > 7 + fr(s.id*3.9 + s.gen)*15) { s.grip = -1; s.held = 0; }
      } else { tgt = -Math.PI*.5 + Math.sin(s.nut)*(.55 + .85*EN) + (fr(s.pts.length*1.9 + s.id)-.5)*.22; }
      let df = tgt - s.ang; while (df > Math.PI) df -= 6.2832; while (df < -Math.PI) df += 6.2832;
      s.ang += df*.3;
