      if (++s.gap >= 3 + Math.round((1-LF)*4)) { s.gap = 0;
        if (s.leaf.length < MAXL) { const li = s.pts.length-1;
          s.leaf.push({ i:li, sg: (li%2)?1:-1, ph: fr(li*3.1 + s.id)*6.28, sz: .75+fr(li*5.9)*.55,
            born: s.age, rt: .8 + fr(li*7.1)*1.9 }); }
