  s.fade = s.age > ph ? cl(1 - (s.age-ph)/s.sen, 0, 1) : 1;
  s.dry  = s.age > ph ? cl((s.age-ph)/s.sen, 0, 1) : 0;
};
if (!S.stems || S.stems.length !== NMAX) {                // warm-up: stagger the generations
  S.stems = [];
  for (let i=0;i<NMAX;i++){ const s = { id:i }; reseed(s);
    const w = fr(i*23.1)*40; for (let q=0; q<Math.round(w*12); q++) adv(s, 1/12);
    S.stems.push(s); }
